INSERT INTO `brands` (`id`, `name`, `slug`, `logo`, `description`) VALUES
(1, 'Apple', 'apple', '', 'Thương hiệu công nghệ hàng đầu thế giới với hệ sinh thái iPhone, Mac, iPad cao cấp.'),
(2, 'Samsung', 'samsung', 'Samsung', 'Gã khổng lồ công nghệ Hàn Quốc tiên phong màn hình AMOLED và trí tuệ nhân tạo Galaxy AI.'),
(3, 'Xiaomi', 'xiaomi', 'Xiaomi', 'Tập đoàn công nghệ với định vị cấu hình vượt trội trên giá thành và camera hợp tác cùng Leica.'),
(4, 'ASUS', 'asus', 'ASUS', 'Nhà sản xuất máy tính và thiết bị gaming hàng đầu với dòng Zenbook tinh tế và ROG huyền thoại.'),
(5, 'Sony', 'sony', 'Sony', 'Biểu tượng âm thanh và hình ảnh Nhật Bản với chuẩn âm thanh đỉnh cao Hi-Res và chống ồn 1000X.'),
(6, 'Dell', 'dell', 'Dell', 'Thương hiệu máy tính xách tay và máy trạm bền bỉ trứ danh cùng dòng cao cấp Dell XPS đột phá.'),
(7, 'Anker', 'anker', 'Anker', 'Hãng phụ kiện sạc nhanh và âm thanh cá nhân số 1 toàn cầu ứng dụng vật liệu bán dẫn GaN.'),
(8, 'Logitech', 'logitech', 'Logitech', 'Thương hiệu Thụy Sĩ đứng đầu thế giới về thiết bị ngoại vi văn phòng công thái học và gaming cao cấp.');
INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `category_name`, `brand_id`, `brand_name`, `price`, `original_price`, `stock`, `rating`, `review_count`, `view_count`, `image`, `images`, `ram`, `rom`, `chipset`, `screen`, `battery`, `camera`, `description`, `featured`, `created_at`) VALUES
(1, 'iPhone 16 Pro Max 256GB', 'iphone-16-pro-max-256gb', 1, 'Điện thoại', 1, 'Apple', 34990000, 37990000, 25, 4.95, 142, 1850, 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=800&auto=format&fit=crop&q=80", "https://images.unsplash.com/photo-1510557880182-3d4d3cba35a5?w=800&auto=format&fit=crop&q=80"]', '8GB', '256GB', 'Apple A18 Pro 3nm', '6.9 inch Super Retina XDR OLED 120Hz', '4685 mAh, Sạc nhanh 30W', 'Chính 48MP + Góc rộng 48MP + Tele 5x 12MP', 'iPhone 16 Pro Max thiết kế Titan sa mạc đẳng cấp, vi xử lý A18 Pro mạnh mẽ và nút Camera Control hoàn toàn mới mang đến trải nghiệm quay chụp điện ảnh đỉnh cao.', 1, '2026-09-20 00:00:00'),
(2, 'iPhone 16 128GB', 'iphone-16-128gb', 1, 'Điện thoại', 1, 'Apple', 21990000, 23990000, 35, 4.88, 89, 1200, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=800&auto=format&fit=crop&q=80"]', '8GB', '128GB', 'Apple A18 3nm', '6.1 inch Super Retina XDR OLED', '3561 mAh, Sạc nhanh 25W', '48MP Fusion + 12MP Ultra Wide', 'iPhone 16 với màu sắc Ultramarine hiện đại, nút chụp Camera Control và hiệu năng bứt phá phục vụ Apple Intelligence.', 1, '2026-09-22 00:00:00'),
(3, 'iPhone 15 Pro 128GB', 'iphone-15-pro-128gb', 1, 'Điện thoại', 1, 'Apple', 24990000, 28990000, 18, 4.85, 110, 950, 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=800&auto=format&fit=crop&q=80"]', '8GB', '128GB', 'Apple A17 Pro', '6.1 inch Super Retina XDR OLED 120Hz ProMotion', '3274 mAh, Sạc nhanh 20W', '48MP + 12MP + 12MP 3x', 'iPhone 15 Pro khung viền Titan cấp hàng không vũ trụ nhẹ và bền, cổng USB-C tốc độ cao và nút Action tùy biến.', 0, '2026-08-10 00:00:00'),
(4, 'Samsung Galaxy S24 Ultra 5G 12GB/256GB', 'samsung-galaxy-s24-ultra', 1, 'Điện thoại', 2, 'Samsung', 29990000, 33990000, 20, 4.9, 105, 1600, 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=800&auto=format&fit=crop&q=80"]', '12GB', '256GB', 'Snapdragon 8 Gen 3 for Galaxy', '6.8 inch Dynamic AMOLED 2X 120Hz 2600 nits', '5000 mAh, Sạc nhanh 45W', '200MP + 50MP + 12MP + 10MP, Zoom 100x', 'Galaxy S24 Ultra khai mở kỷ nguyên Galaxy AI, khung viền Titan sang trọng và bút S-Pen quyền năng.', 1, '2026-08-15 00:00:00'),
(5, 'Samsung Galaxy S24+ 12GB/256GB', 'samsung-galaxy-s24-plus', 1, 'Điện thoại', 2, 'Samsung', 21490000, 26990000, 22, 4.82, 64, 820, 'https://images.unsplash.com/photo-1580910051074-3eb694886505?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1580910051074-3eb694886505?w=800&auto=format&fit=crop&q=80"]', '12GB', '256GB', 'Exynos 2400 Deca-Core', '6.7 inch QHD+ Dynamic AMOLED 2X 120Hz', '4900 mAh, Sạc 45W', '50MP + 12MP + 10MP 3x', 'Galaxy S24+ sở hữu màn hình QHD+ sắc nét, dung lượng pin tăng cường và thiết kế phẳng thanh lịch.', 0, '2026-07-20 00:00:00'),
(6, 'Samsung Galaxy Z Fold6 5G 256GB', 'samsung-galaxy-z-fold6', 1, 'Điện thoại', 2, 'Samsung', 41990000, 43990000, 12, 4.87, 45, 980, 'https://images.unsplash.com/photo-1574944985070-8f3ebc6b79d2?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1574944985070-8f3ebc6b79d2?w=800&auto=format&fit=crop&q=80"]', '12GB', '256GB', 'Snapdragon 8 Gen 3 for Galaxy', '7.6 inch Foldable Dynamic AMOLED 2X 120Hz', '4400 mAh, Sạc 25W', '50MP + 12MP + 10MP', 'Galaxy Z Fold6 thiết kế phẳng mỏng nhẹ hơn bao giờ hết, bản lề Flex Hinge kép mở ra không gian đa nhiệm đỉnh cao.', 1, '2026-08-01 00:00:00'),
(7, 'Xiaomi 14 Ultra 5G 16GB/512GB Leica', 'xiaomi-14-ultra', 1, 'Điện thoại', 3, 'Xiaomi', 28990000, 32990000, 15, 4.89, 78, 1100, 'https://images.unsplash.com/photo-1567581935884-3349723552ca?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1567581935884-3349723552ca?w=800&auto=format&fit=crop&q=80"]', '16GB', '512GB', 'Snapdragon 8 Gen 3', '6.73 inch LTPO AMOLED 120Hz 3000 nits', '5000 mAh, Sạc nhanh 90W', '4 camera Leica 50MP cảm biến 1 inch', 'Xiaomi 14 Ultra hợp tác cùng Leica mang lại hệ thống 4 ống kính quang học Summilux, khẩu độ vô cấp cho ảnh chụp xuất sắc.', 1, '2026-06-15 00:00:00'),
(8, 'Xiaomi 14T Pro 5G 12GB/512GB', 'xiaomi-14t-pro', 1, 'Điện thoại', 3, 'Xiaomi', 16990000, 17990000, 30, 4.8, 52, 750, 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=800&auto=format&fit=crop&q=80"]', '12GB', '512GB', 'MediaTek Dimensity 9300+', '6.67 inch AMOLED 144Hz 4000 nits', '5000 mAh, Sạc 120W HyperCharge', '50MP Leica + 50MP Tele + 12MP Ultra Wide', 'Xiaomi 14T Pro camera Leica thế hệ mới, sạc siêu tốc 120W và hiệu năng Dimensity 9300+ cực khủng.', 0, '2026-09-28 00:00:00'),
(9, 'ASUS ROG Phone 8 Pro 16GB/512GB', 'asus-rog-phone-8-pro', 1, 'Điện thoại', 4, 'ASUS', 27990000, 29990000, 10, 4.92, 63, 890, 'https://images.unsplash.com/photo-1550009158-9ebf69173e03?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1550009158-9ebf69173e03?w=800&auto=format&fit=crop&q=80"]', '16GB', '512GB', 'Snapdragon 8 Gen 3', '6.78 inch Samsung AMOLED 165Hz LTPO', '5500 mAh, Sạc 65W HyperCharge', '50MP Sony IMX890 chống rung Gimbal 6 trục', 'Quái vật gaming ROG Phone 8 Pro với màn hình LED AniMe Vision mặt lưng, tản nhiệt GameCool 8 và nút cảm ứng AirTrigger.', 1, '2026-07-05 00:00:00'),
(10, 'Samsung Galaxy A55 5G 8GB/128GB', 'samsung-galaxy-a55-5g', 1, 'Điện thoại', 2, 'Samsung', 9490000, 9990000, 40, 4.75, 115, 1400, 'https://images.unsplash.com/photo-1585060544812-6b45742d762f?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1585060544812-6b45742d762f?w=800&auto=format&fit=crop&q=80"]', '8GB', '128GB', 'Exynos 1480 4nm', '6.6 inch Super AMOLED 120Hz', '5000 mAh, Sạc 25W', '50MP OIS + 12MP + 5MP', 'Galaxy A55 viền kim loại sang trọng, bảo mật cấp phần cứng Knox Vault và kháng nước bụi chuẩn IP67.', 0, '2026-05-10 00:00:00'),
(11, 'MacBook Pro 14 M3 Pro 18GB/512GB Space Black', 'macbook-pro-14-m3-pro', 2, 'Laptop', 1, 'Apple', 49990000, 52990000, 15, 4.96, 68, 1500, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=800&auto=format&fit=crop&q=80"]', '18GB', '512GB SSD', 'Apple M3 Pro (11 CPU, 14 GPU)', '14.2 inch Liquid Retina XDR 120Hz ProMotion', '70Wh, Thời lượng pin 18 giờ', '1080p FaceTime HD', 'MacBook Pro 14 M3 Pro hiệu năng đồ họa ấn tượng với Dynamic Caching, tản nhiệt tối ưu và màu Space Black cuốn hút.', 1, '2026-07-10 00:00:00'),
(12, 'MacBook Air 13 M3 8GB/256GB Midnight', 'macbook-air-13-m3', 2, 'Laptop', 1, 'Apple', 26990000, 27990000, 28, 4.88, 92, 1350, 'https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?w=800&auto=format&fit=crop&q=80"]', '8GB', '256GB SSD', 'Apple M3 (8 CPU, 8 GPU)', '13.6 inch Liquid Retina True Tone', '52.6Wh, Pin lên tới 18 giờ', '1080p FaceTime HD', 'MacBook Air M3 siêu nhẹ chỉ 1.24kg, hỗ trợ xuất 2 màn hình ngoài cùng thời lượng pin bền bỉ cả ngày làm việc.', 1, '2026-05-20 00:00:00'),
(13, 'MacBook Pro 16 M3 Max 36GB/1TB Silver', 'macbook-pro-16-m3-max', 2, 'Laptop', 1, 'Apple', 89990000, 92990000, 6, 4.98, 31, 720, 'https://images.unsplash.com/photo-1541807084-5c52b6b3adef?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1541807084-5c52b6b3adef?w=800&auto=format&fit=crop&q=80"]', '36GB', '1TB SSD', 'Apple M3 Max (14 CPU, 30 GPU)', '16.2 inch Liquid Retina XDR 1600 nits 120Hz', '100Wh, Pin 22 giờ', '1080p FaceTime HD', 'Đỉnh cao máy trạm di động render 3D chuyên sâu, dựng phim 8K ProRes và huấn luyện mô hình AI không nghẽn cổ chai.', 0, '2026-04-10 00:00:00'),
(14, 'Laptop ASUS ROG Zephyrus G16 OLED RTX 4070', 'asus-rog-zephyrus-g16-oled', 2, 'Laptop', 4, 'ASUS', 59990000, 64990000, 8, 4.91, 45, 1100, 'https://images.unsplash.com/photo-1603302576837-37561b2e2302?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1603302576837-37561b2e2302?w=800&auto=format&fit=crop&q=80"]', '32GB LPDDR5X', '1TB PCIe 4.0 SSD', 'Intel Core Ultra 9 185H', '16.0 inch 2.5K OLED 240Hz 0.2ms Nebula', '90Wh, Sạc 100W Type-C', '1080p FHD IR Windows Hello', 'Laptop Gaming siêu mỏng nhẹ khung nhôm CNC, màn hình OLED 240Hz sắc nét đỉnh cao cùng card đồ họa RTX 4070.', 1, '2026-06-01 00:00:00'),
(15, 'Laptop ASUS Zenbook 14 OLED UX3405 Core Ultra 7', 'asus-zenbook-14-oled-ux3405', 2, 'Laptop', 4, 'ASUS', 29490000, 31990000, 20, 4.86, 56, 890, 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=800&auto=format&fit=crop&q=80"]', '16GB LPDDR5X', '1TB NVMe SSD', 'Intel Core Ultra 7 155H tích hợp NPU AI', '14.0 inch 3K OLED 120Hz 100% DCI-P3', '75Wh, Pin 15 giờ', 'FHD IR Camera', 'Zenbook 14 OLED chuẩn Intel Evo mỏng 14.9mm nặng 1.2kg, màn hình 3K OLED tuyệt mỹ và xử lý AI tăng tốc.', 1, '2026-05-18 00:00:00'),
(16, 'Laptop Gaming ASUS TUF Gaming A15 Ryzen 7 RTX 4060', 'asus-tuf-gaming-a15', 2, 'Laptop', 4, 'ASUS', 25990000, 28990000, 25, 4.79, 74, 980, 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=800&auto=format&fit=crop&q=80"]', '16GB DDR5', '512GB PCIe SSD', 'AMD Ryzen 7 7735HS', '15.6 inch FHD IPS 144Hz 100% sRGB', '90Wh, Sạc nhanh', '720p HD Camera', 'Laptop gaming độ bền chuẩn quân đội MIL-STD-810H, đồ họa RTX 4060 chiến mượt mọi tựa game AAA đỉnh cao.', 0, '2026-06-12 00:00:00'),
(17, 'Dell XPS 14 9440 Core Ultra 7 OLED RTX 4050', 'dell-xps-14-9440', 2, 'Laptop', 6, 'Dell', 54990000, 58990000, 10, 4.93, 38, 790, 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1593642632823-8f785ba67e45?w=800&auto=format&fit=crop&q=80"]', '32GB LPDDR5X', '1TB SSD', 'Intel Core Ultra 7 155H', '14.5 inch 3.2K OLED Touch 120Hz', '69.5Wh, Sạc 100W', '1080p FHD IR', 'Dell XPS 14 ngôn ngữ tương lai kính nguyên khối, trackpad tàng hình cảm ứng lực và bàn phím Zero-lattice sang trọng.', 1, '2026-07-25 00:00:00'),
(18, 'Dell XPS 16 9640 Core Ultra 9 RTX 4070', 'dell-xps-16-9640', 2, 'Laptop', 6, 'Dell', 76990000, 81990000, 5, 4.95, 27, 650, 'https://images.unsplash.com/photo-1587614382346-4ec70e388b28?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1587614382346-4ec70e388b28?w=800&auto=format&fit=crop&q=80"]', '32GB LPDDR5X', '1TB PCIe SSD', 'Intel Core Ultra 9 185H', '16.3 inch 4K+ OLED Touch InfinityEdge', '99.5Wh, Sạc 130W', '1080p FHD IR', 'Kiệt tác công nghệ Dell XPS 16 màn hình 4K OLED tràn viền vô cực cùng sức mạnh xử lý đồ họa chuyên sâu.', 0, '2026-05-30 00:00:00'),
(19, 'Dell Inspiron 14 5440 Core i5-1334U', 'dell-inspiron-14-5440', 2, 'Laptop', 6, 'Dell', 16490000, 18490000, 30, 4.76, 85, 1120, 'https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?w=800&auto=format&fit=crop&q=80"]', '16GB DDR5', '512GB SSD', 'Intel Core i5-1334U', '14.0 inch FHD+ 16:10 Anti-Glare', '54Wh', '1080p FHD Camera', 'Dell Inspiron 14 bền bỉ, bàn phím gõ êm ái, cấu hình 16GB RAM mượt mà phục vụ học tập và công việc văn phòng.', 0, '2026-04-18 00:00:00'),
(20, 'Xiaomi RedmiBook Pro 15 Ryzen 7 8845HS', 'xiaomi-redmibook-pro-15', 2, 'Laptop', 3, 'Xiaomi', 18990000, 20990000, 20, 4.82, 49, 710, 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=800&auto=format&fit=crop&q=80"]', '32GB LPDDR5X', '1TB PCIe 4.0 SSD', 'AMD Ryzen 7 8845HS tích hợp Ryzen AI', '15.6 inch 3.2K 165Hz 500 nits HDR', '80Wh, Sạc 100W GaN', '1080p Full HD', 'RedmiBook Pro 15 vỏ nhôm unibody cao cấp, màn hình 3.2K 165Hz và dung lượng pin khủng 80Wh.', 0, '2026-06-25 00:00:00'),
(21, 'iPad Pro 11 M4 OLED 256GB Wi-Fi Space Black', 'ipad-pro-11-m4-oled', 3, 'Tablet', 1, 'Apple', 27990000, 28990000, 20, 4.97, 72, 1300, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=800&auto=format&fit=crop&q=80"]', '8GB', '256GB', 'Apple M4 9-core CPU, 10-core GPU', '11.0 inch Ultra Retina XDR Tandem OLED 120Hz', '31.29 Wh, Pin 10 giờ', '12MP Wide LiDAR + 12MP Landscape Center Stage', 'iPad Pro M4 thiết kế mỏng không tưởng chỉ 5.3mm, màn hình Tandem OLED đột phá tái định nghĩa công nghệ hiển thị.', 1, '2026-05-25 00:00:00'),
(22, 'iPad Air 6 M2 11 inch 128GB Wi-Fi', 'ipad-air-6-m2-11-inch', 3, 'Tablet', 1, 'Apple', 16490000, 17990000, 30, 4.88, 88, 1420, 'https://images.unsplash.com/photo-1561154464-82e9adf32764?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1561154464-82e9adf32764?w=800&auto=format&fit=crop&q=80"]', '8GB', '128GB', 'Apple M2 8-core CPU', '11.0 inch Liquid Retina True Tone', '28.93 Wh, Pin 10 giờ', '12MP Wide trước & sau', 'iPad Air 6 trang bị vi xử lý Apple M2 mạnh mẽ vượt trội, hỗ trợ bút Apple Pencil Pro thế hệ mới.', 1, '2026-05-22 00:00:00'),
(23, 'iPad Gen 10 10.9 inch 64GB Wi-Fi Pink', 'ipad-gen-10-64gb', 3, 'Tablet', 1, 'Apple', 9490000, 10990000, 45, 4.81, 130, 1600, 'https://images.unsplash.com/photo-1589739900243-4b52cd9b104e?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1589739900243-4b52cd9b104e?w=800&auto=format&fit=crop&q=80"]', '4GB', '64GB', 'Apple A14 Bionic', '10.9 inch Liquid Retina IPS', '28.6 Wh, Pin 10 giờ', '12MP Wide trước & sau', 'iPad Gen 10 thiết kế vuông vức tràn viền, 4 sắc màu cá tính và cổng kết nối Type-C tiện dụng.', 0, '2026-04-15 00:00:00'),
(24, 'Samsung Galaxy Tab S9 Ultra 12GB/256GB S-Pen', 'samsung-galaxy-tab-s9-ultra', 3, 'Tablet', 2, 'Samsung', 23990000, 27990000, 12, 4.92, 53, 850, 'https://images.unsplash.com/photo-1585792180666-f7547c6a28c5?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1585792180666-f7547c6a28c5?w=800&auto=format&fit=crop&q=80"]', '12GB', '256GB', 'Snapdragon 8 Gen 2 for Galaxy', '14.6 inch Dynamic AMOLED 2X 120Hz', '11200 mAh, Sạc 45W', '13MP + 8MP sau, Kép 12MP trước', 'Galaxy Tab S9 Ultra màn hình khổng lồ 14.6 inch, chuẩn kháng nước IP68 đầu tiên và bút S-Pen sáng tạo.', 1, '2026-06-18 00:00:00'),
(25, 'Samsung Galaxy Tab S9 FE 6GB/128GB S-Pen', 'samsung-galaxy-tab-s9-fe', 3, 'Tablet', 2, 'Samsung', 8990000, 9990000, 25, 4.79, 67, 920, 'https://images.unsplash.com/photo-1527698266440-12104e498b76?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1527698266440-12104e498b76?w=800&auto=format&fit=crop&q=80"]', '6GB', '128GB', 'Exynos 1380', '10.9 inch IPS LCD 90Hz', '8000 mAh, Sạc 45W', '8MP sau, 12MP trước', 'Tab S9 FE kèm sẵn bút S-Pen trong hộp, thời lượng pin cả ngày dài và loa kép AKG sống động.', 0, '2026-05-02 00:00:00'),
(26, 'Xiaomi Pad 6S Pro 12.4 inch 8GB/256GB', 'xiaomi-pad-6s-pro', 3, 'Tablet', 3, 'Xiaomi', 13990000, 14990000, 20, 4.84, 42, 680, 'https://images.unsplash.com/photo-1561154464-82e9adf32764?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1561154464-82e9adf32764?w=800&auto=format&fit=crop&q=80"]', '8GB', '256GB', 'Snapdragon 8 Gen 2', '12.4 inch 3K 144Hz 3:2 tỉ lệ vàng', '10000 mAh, Sạc 120W HyperCharge', '50MP sau, 32MP trước', 'Xiaomi Pad 6S Pro màn hình 3K 144Hz tỉ lệ 3:2 làm việc tối ưu, sạc đầy 100% pin chỉ trong 35 phút.', 0, '2026-06-08 00:00:00'),
(27, 'Tai nghe Sony WH-1000XM5 Chống Ồn Flagship', 'sony-wh-1000xm5', 4, 'Âm thanh', 5, 'Sony', 7490000, 8990000, 30, 4.93, 168, 1950, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Sony Integrated Processor V1 + HD QN1', 'Driver 30mm sợi carbon cao cấp', 'Pin 30 giờ (bật ANC), Sạc 3 phút nghe 3 giờ', '8 micro AI lọc gió', 'Công nghệ chống ồn số 1 thị trường, âm thanh chuẩn Hi-Res Audio Wireless LDAC đem lại trải nghiệm thư thái tuyệt đối.', 1, '2026-05-18 00:00:00'),
(28, 'Tai nghe Sony WF-1000XM5 True Wireless', 'sony-wf-1000xm5', 4, 'Âm thanh', 5, 'Sony', 5990000, 6990000, 25, 4.87, 94, 1250, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Sony V2 + QN2e Dual Processor', 'Driver Dynamic X 8.4mm tái tạo âm trầm sâu', 'Pin 8 giờ + 16 giờ hộp sạc, IPX4', '3 micro mỗi bên + Cảm biến xương Bone conduction', 'Tai nghe in-ear chống ồn đỉnh cao, kích thước thu gọn 25% đeo vừa vặn êm ái suốt cả ngày dài.', 1, '2026-04-20 00:00:00'),
(29, 'Loa Bluetooth Sony SRS-XE300 Kháng nước IP67', 'sony-srs-xe300', 4, 'Âm thanh', 5, 'Sony', 3490000, 4290000, 20, 4.8, 51, 620, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1545454675-3531b543be5d?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Bộ khuếch tán âm Line-Shape Diffuser', 'Màng loa X-Balanced Speaker Unit', 'Pin 24 giờ, Chống sốc, chống nước IP67', 'Micro đàm thoại khử vọng', 'Loa di động âm thanh lan tỏa rộng khắp không gian, chống nước chống bụi chuẩn biển dã ngoại.', 0, '2026-03-15 00:00:00'),
(30, 'Tai nghe Apple AirPods Pro 2 USB-C MagSafe', 'apple-airpods-pro-2-usb-c', 4, 'Âm thanh', 1, 'Apple', 5490000, 6190000, 40, 4.94, 210, 2300, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Apple H2 chip + U1 chip hộp sạc', 'Driver Apple độ méo thấp tùy chỉnh', 'Pin 6 giờ (30 giờ kèm hộp sạc), Sạc MagSafe/USB-C', 'Chống ồn chủ động gấp 2 lần + Adaptive Audio', 'AirPods Pro 2 âm thanh không gian cá nhân hóa, chống ồn chủ động vượt trội và hộp sạc tìm kiếm Precision Finding.', 1, '2026-06-20 00:00:00'),
(31, 'Tai nghe Apple AirPods Max USB-C 2024', 'apple-airpods-max-usb-c', 4, 'Âm thanh', 1, 'Apple', 13290000, 13990000, 10, 4.85, 48, 850, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Apple H1 chip mỗi bên tai nghe', 'Driver 40mm động học do Apple thiết kế', 'Pin 20 giờ bật ANC và Âm thanh không gian', '9 micro lọc âm đàm thoại trong trẻo', 'Thiết kế trùm tai sang trọng với khung thép không gỉ, đệm tai dạng lưới thoáng khí và âm thanh độ trung thực cao.', 0, '2026-09-21 00:00:00'),
(32, 'Tai nghe Samsung Galaxy Buds3 Pro Galaxy AI', 'samsung-galaxy-buds3-pro', 4, 'Âm thanh', 2, 'Samsung', 4990000, 5490000, 25, 4.82, 60, 780, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Dual Amp + Samsung Seamless Codec 24bit/96kHz', 'Loa 2 chiều Woofer 10.5mm + Tweeter phẳng 6.1mm', 'Pin 7 giờ + 30 giờ hộp sạc', 'Dải đèn Blade Lights + Khử ồn thông minh AI', 'Thiết kế dạng thân mới tích hợp đèn LED Blade Lights, âm thanh Hi-Fi 24-bit và phiên dịch trực tiếp qua Galaxy AI.', 0, '2026-07-28 00:00:00'),
(33, 'Tai nghe Xiaomi Redmi Buds 5 Pro Chống Ồn 52dB', 'xiaomi-redmi-buds-5-pro', 4, 'Âm thanh', 3, 'Xiaomi', 1490000, 1790000, 50, 4.77, 82, 950, 'https://images.unsplash.com/photo-1572536147248-ac59a8abfa4b?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1572536147248-ac59a8abfa4b?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Codec LHDC 5.0 chuẩn Hi-Res Audio Wireless', 'Driver kép đồng trục loa trầm titan 11mm + gốm 10mm', 'Pin 10 giờ (38 giờ hộp sạc), Sạc nhanh 5 phút', 'Chống ồn sâu 52dB tần số siêu rộng 4kHz', 'Tai nghe chống ồn tốt nhất phân khúc dưới 2 triệu đồng, màng loa gốm cao cấp và âm thanh Hi-Res chi tiết.', 0, '2026-05-12 00:00:00'),
(34, 'Loa Bluetooth Anker Soundcore Motion Boom Plus 80W', 'anker-soundcore-motion-boom-plus', 4, 'Âm thanh', 7, 'Anker', 3290000, 3990000, 20, 4.88, 64, 710, 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Công nghệ tăng cường âm trầm BassUp', 'Công suất 80W (2 Woofer 30W + 2 Tweeter 10W)', 'Pin 13400 mAh, phát nhạc 20 giờ kiêm sạc dự phòng', 'Chống nước và nổi trên mặt nước chuẩn IP67', 'Loa tiệc ngoài trời công suất bùng nổ 80W, chống nước hoàn hảo nổi được trên mặt nước cho các chuyến dã ngoại.', 0, '2026-04-18 00:00:00'),
(35, 'Apple Watch Ultra 2 GPS + Cellular 49mm Titanium', 'apple-watch-ultra-2', 5, 'Smartwatch & Phụ kiện', 1, 'Apple', 20990000, 22990000, 15, 4.95, 76, 1200, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80"]', NULL, '64GB', 'Apple S9 SiP 64-bit + Chip UWB thế hệ 2', 'OLED LTPO Always-On 3000 nits đỉnh sáng', 'Pin 36 giờ (72 giờ chế độ nguồn điện thấp)', 'Còi báo động 86dB + Kháng nước 100m chuẩn lặn EN13319', 'Đồng hồ thể thao dã ngoại chuyên nghiệp, vỏ Titan tái chế bền bỉ và độ sáng màn hình 3000 nits thách thức ánh mặt trời.', 1, '2026-05-05 00:00:00'),
(36, 'Apple Watch Series 9 GPS 45mm Nhôm Midnight', 'apple-watch-series-9-45mm', 5, 'Smartwatch & Phụ kiện', 1, 'Apple', 10490000, 11290000, 25, 4.86, 92, 1150, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=800&auto=format&fit=crop&q=80"]', NULL, '64GB', 'Apple S9 SiP lõi tứ Neural Engine', 'OLED LTPO Always-On 2000 nits', 'Pin 18 giờ, Sạc nhanh 0-80% trong 45 phút', 'Cảm biến ECG, SpO2, đo nhiệt độ cổ tay', 'Apple Watch Series 9 thao tác chạm 2 ngón Double Tap kỳ diệu, màn hình sáng gấp đôi và theo dõi sức khỏe chuyên sâu.', 1, '2026-04-25 00:00:00'),
(37, 'Samsung Galaxy Watch Ultra 47mm LTE Titanium', 'samsung-galaxy-watch-ultra', 5, 'Smartwatch & Phụ kiện', 2, 'Samsung', 16490000, 17990000, 12, 4.9, 48, 870, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800&auto=format&fit=crop&q=80"]', '2GB', '32GB', 'Exynos W1000 3nm 5 nhân', 'Super AMOLED 1.5 inch 3000 nits kính Sapphire', '590 mAh, Pin lên tới 100 giờ ở chế độ tiết kiệm', 'Cảm biến BioActive + Đo chỉ số AGEs chống lão hóa', 'Galaxy Watch Ultra thiết kế vỏ đệm Cushion độc đáo, GPS tần số kép L1+L5 chính xác và năng lực AI chăm sóc sức khỏe.', 1, '2026-07-22 00:00:00'),
(38, 'Samsung Galaxy Watch6 Classic 43mm Bluetooth', 'samsung-galaxy-watch-6-classic', 5, 'Smartwatch & Phụ kiện', 2, 'Samsung', 6490000, 7990000, 18, 4.81, 65, 760, 'https://images.unsplash.com/photo-1510017803434-a899398421b3?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1510017803434-a899398421b3?w=800&auto=format&fit=crop&q=80"]', '2GB', '16GB', 'Exynos W930 1.4GHz', 'Super AMOLED 1.3 inch Sapphire', '300 mAh, Sạc nhanh không dây', 'Cảm biến huyết áp, ECG, BIA phân tích cơ thể', 'Vòng xoay bezel vật lý trứ danh, màn hình lớn hơn 20% và huấn luyện viên giấc ngủ cá nhân hóa mỗi ngày.', 0, '2026-03-28 00:00:00'),
(39, 'Củ sạc nhanh Anker 65W GaNPrime 3 cổng A2668', 'cu-sac-anker-65w-ganprime', 5, 'Smartwatch & Phụ kiện', 7, 'Anker', 890000, 1150000, 60, 4.9, 184, 1890, 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Công nghệ GaNPrime thế hệ mới nhất', '2 cổng USB-C (Max 65W) + 1 cổng USB-A (22.5W)', 'Bảo vệ nhiệt ActiveShield 2.0 kiểm soát nhiệt', 'Chuẩn Power Delivery 3.0 và PPS Samsung', 'Củ sạc siêu nhỏ gọn nhẹ hơn 38% củ sạc hãng, phân bổ công suất thông minh PowerIQ 4.0 sạc cùng lúc MacBook, iPhone và iPad.', 1, '2026-04-12 00:00:00'),
(40, 'Củ sạc nhanh Anker 100W GaNPrime A2343', 'cu-sac-anker-100w-ganprime', 5, 'Smartwatch & Phụ kiện', 7, 'Anker', 1290000, 1590000, 40, 4.92, 98, 1200, 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Công nghệ GaN thế hệ mới', '2 cổng USB-C + 1 cổng USB-A (Công suất đơn max 100W)', 'ActiveShield 2.0 bảo vệ an toàn cháy nổ', 'Tương thích laptop Dell XPS, MacBook Pro 16', 'Củ sạc 100W mạnh mẽ sạc đầy 50% pin MacBook Pro 16 inch chỉ trong 30 phút, đồng thời sạc nhanh điện thoại và phụ kiện.', 0, '2026-05-15 00:00:00'),
(41, 'Chuột không dây Logitech MX Master 3S Quiet Clicks', 'logitech-mx-master-3s', 5, 'Smartwatch & Phụ kiện', 8, 'Logitech', 2190000, 2490000, 35, 4.96, 175, 1750, 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Cảm biến Darkfield 8000 DPI trên mọi bề mặt kính', 'Cuộn điện từ MagSpeed cuộn 1000 dòng/giây', 'Pin sạc 500mAh dùng 70 ngày, Sạc nhanh USB-C', 'Nút click êm ái giảm 90% tiếng ồn + Kết nối 3 thiết bị', 'Chuột công thái học cao cấp tốt nhất cho lập trình viên và nhà sáng tạo, con lăn điện từ MagSpeed và cảm biến 8000 DPI lướt mượt trên kính.', 1, '2026-04-08 00:00:00'),
(42, 'Bàn phím cơ không dây Logitech MX Mechanical Tactile', 'logitech-mx-mechanical', 5, 'Smartwatch & Phụ kiện', 8, 'Logitech', 3390000, 3790000, 25, 4.91, 88, 1100, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Switch cơ học Low Profile độ nảy cao', 'Đèn nền thông minh tự động bật sáng khi tay lại gần', 'Pin sạc USB-C dùng 15 ngày có đèn (10 tháng tắt đèn)', 'Kết nối 3 thiết bị chuyển đổi tức thì', 'Bàn phím cơ low-profile gõ cực kỳ êm ái, plate nhôm mờ cao cấp và đèn nền tự cảm biến khoảng cách tay thông minh.', 1, '2026-04-10 00:00:00');
